import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
  ResponsiveContainer, ReferenceLine, LabelList, Cell,
} from 'recharts'
import api from '../../api'
import { Card, Stat } from '../../components/ui.jsx'

/**
 * AI/ML Evaluation tab (inside Analytics): detection rate, false alarms,
 * ROC / PR / confusion matrix, calibration, fairness audit, SHAP, detection &
 * response time, and the model registry. Numbers come from
 * POST /ml/evaluation/run -- labelled scenarios generated by the Simulation
 * Core and scored by the production detectors (backend services/evaluation.py).
 */

const C = { blue: '#2a78d6', green: '#008300', orange: '#eb6834', amber: '#eda100', purple: '#4a3aa7', grey: '#898781' }
const INK = { grid: '#e1e0d9', axis: '#898781' }
const SIZES = [50, 100, 200, 500]

const pct = (v, d = 1) => (v == null ? '—' : `${(v * 100).toFixed(d)}%`)
const num = (v, d = 2) => (v == null ? '—' : Number(v).toFixed(d))
const dur = (s) => (s == null ? '—' : s >= 120 ? `${(s / 60).toFixed(1)} min` : `${Math.round(s)} s`)

// Cell shading: goodness in [0,1] -> green (good) .. red (bad). Text always shown, never colour alone.
const heat = (good) => (good == null ? undefined : {
  background: good >= 0.5
    ? `rgba(12,163,12,${(0.08 + 0.3 * (good - 0.5) * 2).toFixed(2)})`
    : `rgba(208,59,59,${(0.08 + 0.3 * (0.5 - good) * 2).toFixed(2)})`,
})

function Chip({ children, tone = 'slate' }) {
  const tones = {
    slate: 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-200',
    green: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300',
    amber: 'bg-amber-100 text-amber-800 dark:bg-amber-900/40 dark:text-amber-300',
    red: 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300',
    blue: 'bg-sky-100 text-sky-800 dark:bg-sky-900/40 dark:text-sky-300',
  }
  return <span className={`px-2 py-0.5 rounded-full text-[11px] font-semibold ${tones[tone]}`}>{children}</span>
}

function Toggle({ value, onChange, options, label }) {
  return (
    <div role="group" aria-label={label} className="flex rounded-lg overflow-hidden border border-slate-200 dark:border-slate-600">
      {options.map(([k, text]) => (
        <button key={k} onClick={() => onChange(k)} aria-pressed={value === k}
          className={`px-2 py-0.5 text-[11px] font-semibold ${value === k
            ? 'bg-sky-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400'}`}>{text}</button>
      ))}
    </div>
  )
}

function Table({ head, children }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="text-left text-[11px] uppercase tracking-wide text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-700">
            {head.map((h) => <th key={h} className="py-2 pr-3 font-semibold whitespace-nowrap">{h}</th>)}
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100 dark:divide-slate-700/60">{children}</tbody>
      </table>
    </div>
  )
}

const axis = { tick: { fill: INK.axis, fontSize: 11 }, tickLine: false }

function CurveChart({ data, xLabel, yLabel, diagonal = false, color = C.blue, name }) {
  return (
    <ResponsiveContainer width="100%" height={250}>
      <LineChart data={data} margin={{ top: 8, right: 16, bottom: 18, left: 0 }}>
        <CartesianGrid stroke={INK.grid} />
        <XAxis type="number" dataKey="x" domain={[0, 1]} {...axis} label={{ value: xLabel, position: 'insideBottom', offset: -10, fill: INK.axis, fontSize: 11 }} />
        <YAxis type="number" domain={[0, 1]} {...axis} label={{ value: yLabel, angle: -90, position: 'insideLeft', fill: INK.axis, fontSize: 11 }} />
        <Tooltip formatter={(v) => num(v, 3)} labelFormatter={(v) => `${xLabel}: ${num(v, 3)}`} />
        {diagonal && <ReferenceLine segment={[{ x: 0, y: 0 }, { x: 1, y: 1 }]} stroke={C.grey} strokeDasharray="5 5" />}
        <Line type="monotone" dataKey="y" name={name} stroke={color} strokeWidth={2} dot={false} isAnimationActive={false} />
      </LineChart>
    </ResponsiveContainer>
  )
}

function ConfusionMatrix({ cm }) {
  const max = Math.max(1, cm.tn, cm.fp, cm.fn, cm.tp)
  const cell = (v, good, label) => (
    <div className="relative flex flex-col items-center justify-center h-24 rounded-md"
      style={{ background: `${good ? '#1f5d78' : '#c0392b'}${Math.round(20 + 200 * (v / max)).toString(16).padStart(2, '0')}` }}>
      <div className="text-2xl font-bold text-slate-900 dark:text-white">{v}</div>
      <div className="text-[10px] uppercase tracking-wide text-slate-700 dark:text-slate-200">{label}</div>
    </div>
  )
  return (
    <div className="flex gap-2 items-stretch">
      <div className="flex items-center text-[11px] text-slate-500 [writing-mode:vertical-rl] rotate-180">Actual scenario</div>
      <div className="flex-1">
        <div className="grid grid-cols-2 gap-1.5">
          {cell(cm.tn, true, 'Safe, not flagged')}{cell(cm.fp, false, 'Safe, false alarm')}
          {cell(cm.fn, false, 'Missed')}{cell(cm.tp, true, 'Detected')}
        </div>
        <div className="grid grid-cols-2 text-center text-[11px] text-slate-500 mt-1"><span>Predicted: safe</span><span>Predicted: suspicious</span></div>
        <div className="text-center text-[11px] text-slate-500">rows: actual safe / actual suspicious</div>
      </div>
    </div>
  )
}

export default function MlEvaluation() {
  const [data, setData] = useState(null)          // { latest, history }
  const [report, setReport] = useState(null)
  const [registry, setRegistry] = useState(null)
  const [drift, setDrift] = useState(null)
  const [loading, setLoading] = useState(true)
  const [running, setRunning] = useState(false)
  const [error, setError] = useState('')
  const [size, setSize] = useState(100)
  const [seed, setSeed] = useState('')
  const [calModel, setCalModel] = useState('anomaly_model')
  const [rocModel, setRocModel] = useState('system')
  const [fairAttr, setFairAttr] = useState('traveller_type')
  const [fairDet, setFairDet] = useState('system')

  const load = useCallback(async () => {
    try {
      const { data: d } = await api.get('/ml/evaluation/latest')
      setData(d)
      setReport(d.latest)
    } catch (e) {
      setError(e?.response?.data?.detail || 'Could not load evaluation results.')
    } finally { setLoading(false) }
  }, [])

  useEffect(() => {
    load()
    api.get('/ml/registry').then((r) => setRegistry(r.data)).catch(() => {})
    api.get('/ml/drift').then((r) => setDrift(r.data)).catch(() => {})
  }, [load])

  const run = async () => {
    setRunning(true); setError('')
    try {
      const body = { n_scenarios: size }
      if (seed !== '') body.seed = Number(seed)
      const { data: r } = await api.post('/ml/evaluation/run', body)
      setReport(r)
      const { data: d } = await api.get('/ml/evaluation/latest')
      setData(d)
    } catch (e) {
      setError(e?.response?.data?.detail || 'Evaluation failed.')
    } finally { setRunning(false) }
  }

  const openRun = async (id) => {
    if (!id) return
    try { setReport((await api.get(`/ml/evaluation/runs/${id}`)).data) } catch { setError('That run is no longer stored.') }
  }

  const h = report?.headline
  const toXY = (pts) => (pts || []).map(([x, y]) => ({ x, y }))
  const trend = useMemo(() => (data?.history || []).map((r, i) => ({
    run: `#${i + 1}`, detection: r.detection_rate, false_alarm: r.false_positive_rate, precision: r.precision,
  })), [data])
  const cal = report?.curves.calibration[calModel]
  const calPts = (cal?.points || []).map((p) => ({ x: p.pred, observed: p.obs, perfect: p.pred, n: p.n }))
  // Pad with the 0 and 1 ends so the "perfect" diagonal always spans the whole chart.
  const calData = calPts.length ? [{ x: 0, perfect: 0 }, ...calPts, { x: 1, perfect: 1 }] : []
  const fair = report?.fairness[fairAttr]?.[fairDet]
  const fairBars = (fair?.groups || []).map((g) => ({
    group: `${g.group} (n=${g.n})`, under: g.fnr == null ? 0 : -g.fnr * 100, over: g.fpr == null ? 0 : g.fpr * 100,
  }))
  const shap = report?.explainability?.mean_abs_contribution
  const shapRows = shap ? Object.entries(shap).map(([k, v]) => ({ feature: k, value: v })).sort((a, b) => b.value - a.value) : []
  const resp = report?.response

  return (
    <div className="space-y-4">
      {/* ------------------------------------------------ header + run controls */}
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-lg font-bold text-slate-100">AI/ML Model Evaluation</h2>
          <p className="text-sm text-slate-300">
            Are the models accurate, reliable and fair? Labelled scenarios from the Simulation Core, scored by the production detectors.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <label className="text-xs text-slate-300 flex items-center gap-1">Scenarios
            <select value={size} onChange={(e) => setSize(Number(e.target.value))} aria-label="Scenarios"
              className="px-2 py-1 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm">
              {SIZES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
          </label>
          <label className="text-xs text-slate-300 flex items-center gap-1">Seed
            <input value={seed} onChange={(e) => setSeed(e.target.value.replace(/\D/g, ''))} placeholder="random" aria-label="Seed"
              className="w-20 px-2 py-1 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm" />
          </label>
          <button onClick={run} disabled={running}
            className="px-4 py-1.5 rounded-lg bg-sky-600 hover:bg-sky-500 text-white text-sm font-semibold disabled:opacity-60">
            {running ? 'Running…' : report ? '↻ Re-run evaluation' : '▶ Run evaluation'}
          </button>
          {data?.history?.length > 1 && (
            <select value={report?.run_id || ''} onChange={(e) => openRun(e.target.value)} aria-label="Past runs"
              className="px-2 py-1 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm">
              {[...data.history].reverse().map((r) => (
                <option key={r.run_id} value={r.run_id}>{r.created_at.slice(0, 16).replace('T', ' ')} · {r.n_scenarios} · seed {r.seed}</option>
              ))}
            </select>
          )}
        </div>
      </div>

      {error && <div role="alert" className="rounded-lg border border-red-300 bg-red-50 text-red-700 text-sm px-3 py-2">{error}</div>}

      {loading ? <div className="text-slate-500 text-sm">Loading…</div> : !report ? (
        <Card><div className="p-6 text-center text-slate-600 dark:text-slate-300">
          <div className="text-3xl mb-2">🧪</div>
          <div className="font-semibold">No evaluation has been run yet.</div>
          <div className="text-sm text-slate-500 mt-1">Press <b>Run evaluation</b> to generate labelled scenarios and measure the models (takes a few seconds).</div>
        </div></Card>
      ) : (
        <>
          <div className="rounded-lg border border-amber-300/70 bg-amber-50 dark:bg-amber-900/20 text-amber-900 dark:text-amber-200 text-xs px-3 py-2">
            <b>Read this honestly.</b> Scenario labels come from scripted <i>simulated</i> behaviour, so these figures measure detection of those behaviours — not real-world accuracy.
            {' '}Run <b>{report.run_id}</b> · {report.totals.n_scenarios} scenarios ({report.totals.n_suspicious} suspicious / {report.totals.n_safe} safe) · {report.totals.n_pings.toLocaleString()} GPS pings · seed {report.config.seed} · {report.duration_s}s · inference mode: {report.models.inference_mode}
            {' '}· model versions: anomaly v{report.models.active_versions.anomaly ?? '?'}, safety v{report.models.active_versions.safety ?? '?'}.
          </div>

          {/* ------------------------------------------------ KPI tiles */}
          <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-5 gap-3">
            <Stat label="Scenarios tested" value={report.totals.n_scenarios} />
            <Stat label="Detection rate (recall)" value={pct(h.detection_rate)} accent="text-emerald-600" />
            <Stat label="False alarm rate" value={pct(h.false_positive_rate)} accent="text-orange-600" />
            <Stat label="Precision" value={pct(h.precision)} />
            <Stat label="F1 score" value={num(h.f1, 3)} />
            <Stat label="ROC-AUC" value={num(h.roc_auc, 3)} />
            <Stat label="Avg detection delay" value={h.avg_detection_delay_min == null ? '—' : `${num(h.avg_detection_delay_min, 1)} min`} />
            <Stat label="Median detection delay" value={h.median_detection_delay_min == null ? '—' : `${num(h.median_detection_delay_min, 1)} min`} />
            <Stat label="Model inference" value={`${num(h.inference_ms_per_ping, 3)} ms`} />
            <Stat label="Avg response (acknowledge)" value={resp?.all.acknowledge.n ? dur(resp.all.acknowledge.mean_s) : '—'} />
          </div>
          <div className="text-xs text-slate-400 -mt-2">
            Detection delay = simulated minutes from the start of the event to the first flagged ping (depends on ping cadence). Inference = real wall-clock per ping.
            {' '}Response time comes from real incident timestamps (n = {resp?.all.acknowledge.n ?? 0} acknowledged).
            {' '}At a realistic 5% prevalence, expected precision would be <b>{pct(h.expected_precision_at_5pct_prevalence)}</b>; {pct(h.ping_false_alarm_rate)} of safe pings raised a flag.
          </div>

          {/* ------------------------------------------------ trend + ROC / PR / confusion */}
          {trend.length > 1 && (
            <Card title="Metrics across evaluation runs">
              <ResponsiveContainer width="100%" height={220}>
                <LineChart data={trend} margin={{ top: 10, right: 16, bottom: 0, left: -10 }}>
                  <CartesianGrid stroke={INK.grid} vertical={false} />
                  <XAxis dataKey="run" {...axis} /><YAxis domain={[0, 1]} tickFormatter={(v) => `${v * 100}%`} {...axis} axisLine={false} />
                  <Tooltip formatter={(v) => pct(v)} /><Legend />
                  <Line dataKey="detection" name="Detection rate" stroke={C.green} strokeWidth={2} />
                  <Line dataKey="false_alarm" name="False alarm rate" stroke={C.orange} strokeWidth={2} />
                  <Line dataKey="precision" name="Precision" stroke={C.blue} strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            </Card>
          )}

          <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
            <Card title="ROC curve" actions={
              <Toggle label="ROC model" value={rocModel} onChange={setRocModel} options={[['system', 'System'], ['anomaly_model', 'Isolation Forest']]} />}>
              <CurveChart data={toXY(report.curves.roc[rocModel])} xLabel="False positive rate" yLabel="True positive rate" diagonal name="ROC" />
              <div className="text-xs text-slate-500 text-center">AUC {num(report.detectors.find((d) => d.key === rocModel)?.auc, 3)}</div>
            </Card>
            <Card title="Precision–Recall">
              <CurveChart data={toXY(report.curves.pr[rocModel])} xLabel="Recall" yLabel="Precision" color={C.purple} name="PR" />
              <div className="text-xs text-slate-500 text-center">Same model selection as the ROC card</div>
            </Card>
            <Card title="Confusion matrix (system, per scenario)"><ConfusionMatrix cm={report.confusion} /></Card>
          </div>

          {/* ------------------------------------------------ model comparison */}
          <Card title="Model-wise performance comparison">
            <Table head={['Detector', 'Type', 'Detection rate', 'False alarm rate', 'Precision', 'F1', 'AUC']}>
              {report.detectors.map((d) => (
                <tr key={d.key} className={d.key === 'system' ? 'font-semibold' : ''}>
                  <td className="py-2 pr-3">{d.name}</td>
                  <td className="py-2 pr-3"><Chip tone={d.type === 'ML' ? 'blue' : d.type === 'System' ? 'green' : 'slate'}>{d.type}</Chip></td>
                  <td className="py-2 pr-3 px-2" style={heat(d.recall)}>{pct(d.recall)}</td>
                  <td className="py-2 pr-3 px-2" style={heat(d.fpr == null ? null : 1 - d.fpr)}>{pct(d.fpr)}</td>
                  <td className="py-2 pr-3 px-2" style={heat(d.precision)}>{pct(d.precision)}</td>
                  <td className="py-2 pr-3 px-2" style={heat(d.f1)}>{num(d.f1, 3)}</td>
                  <td className="py-2 pr-3 px-2" style={heat(d.auc)}>{num(d.auc, 3)}</td>
                </tr>
              ))}
            </Table>
            <p className="text-xs text-slate-500 mt-2">
              Rules (route deviation, geofence) rarely false-alarm but miss many cases on their own; the ML models and the combined system trade some false alarms for coverage.
              The safety Random Forest flags a scenario when its safety score drops below 50.
            </p>
          </Card>

          <Card title="Performance by scenario type">
            <Table head={['Scenario', 'Truth', 'n', 'System result', 'Isolation Forest', 'Route rule', 'Geofence', 'Avg delay']}>
              {report.by_scenario.map((s) => {
                const sus = s.label === 'suspicious'
                return (
                  <tr key={s.kind}>
                    <td className="py-2 pr-3">{s.name}</td>
                    <td className="py-2 pr-3"><Chip tone={sus ? 'red' : 'green'}>{s.label}</Chip></td>
                    <td className="py-2 pr-3">{s.n}</td>
                    <td className="py-2 pr-3 px-2" style={heat(sus ? s.rate : 1 - s.rate)}>
                      {sus ? `detected ${s.flagged}/${s.n} (${pct(s.rate, 0)})` : `false alarms ${s.flagged}/${s.n} (${pct(s.rate, 0)})`}
                    </td>
                    {['anomaly_model', 'route_deviation', 'geofence'].map((k) => (
                      <td key={k} className="py-2 pr-3 px-2" style={heat(sus ? s.by_detector[k] : 1 - s.by_detector[k])}>{pct(s.by_detector[k], 0)}</td>
                    ))}
                    <td className="py-2 pr-3">{s.avg_delay_min == null ? '—' : `${num(s.avg_delay_min, 1)} min`}</td>
                  </tr>
                )
              })}
            </Table>
            <p className="text-xs text-slate-500 mt-2">
              Green = good for that row’s truth (high detection for suspicious, low false alarms for safe). The “safe” hard cases (taxi rides, signal gaps) are where the models are weakest.
              Inactivity is only noticed when the device reports again, so its delay is roughly the silent period.
            </p>
          </Card>

          {/* ------------------------------------------------ calibration */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            <Card title="Calibration curve" actions={
              <Toggle label="Calibration model" value={calModel} onChange={setCalModel}
                options={[['anomaly_model', 'Isolation Forest'], ['safety_rf', 'Safety RF'], ['system', 'System']]} />}>
              <ResponsiveContainer width="100%" height={270}>
                <LineChart data={calData} margin={{ top: 8, right: 16, bottom: 18, left: 0 }}>
                  <CartesianGrid stroke={INK.grid} strokeDasharray="4 4" />
                  <XAxis type="number" dataKey="x" domain={[0, 1]} {...axis} label={{ value: 'Predicted probability', position: 'insideBottom', offset: -10, fill: INK.axis, fontSize: 11 }} />
                  <YAxis type="number" domain={[0, 1]} {...axis} label={{ value: 'Observed frequency', angle: -90, position: 'insideLeft', fill: INK.axis, fontSize: 11 }} />
                  <Tooltip formatter={(v) => num(v, 3)} /><Legend verticalAlign="top" />
                  <Line dataKey="perfect" name="Perfect calibration" stroke={C.grey} strokeDasharray="6 6" dot={false} isAnimationActive={false} />
                  <Line dataKey="observed" name="Model calibration" stroke={C.blue} strokeWidth={2.5} dot={{ r: 4 }} connectNulls isAnimationActive={false} />
                </LineChart>
              </ResponsiveContainer>
              <div className="flex gap-4 text-xs text-slate-500 justify-center">
                <span>Brier score <b>{num(cal?.brier, 3)}</b></span>
                <span>Expected calibration error <b>{num(cal?.ece, 3)}</b></span>
                <span>{calPts.length ? `${calPts.length} populated bins` : 'not enough data'}</span>
              </div>
              <p className="text-xs text-slate-500 mt-1">
                A point above the dotted line means the model under-states risk there; below, it over-states it. The Isolation Forest score is a squashed anomaly score, not a trained probability — this chart shows how far from calibrated it is.
              </p>
            </Card>
            <Card title="Predicted anomaly score distribution">
              <ResponsiveContainer width="100%" height={270}>
                <BarChart data={report.curves.score_hist} margin={{ top: 8, right: 16, bottom: 18, left: -8 }}>
                  <CartesianGrid stroke={INK.grid} vertical={false} />
                  <XAxis dataKey="bin" {...axis} interval={0} angle={-30} textAnchor="end" height={50} />
                  <YAxis allowDecimals={false} {...axis} axisLine={false} />
                  <Tooltip /><Legend verticalAlign="top" />
                  <Bar dataKey="safe" name="Safe scenarios" stackId="a" fill={C.blue} />
                  <Bar dataKey="suspicious" name="Suspicious scenarios" stackId="a" fill={C.orange} />
                </BarChart>
              </ResponsiveContainer>
              <p className="text-xs text-slate-500">Good separation = safe scenarios pile up on the left, suspicious ones on the right.</p>
            </Card>
          </div>

          {/* ------------------------------------------------ fairness */}
          <Card title="Fairness audit" actions={
            <div className="flex gap-2">
              <Toggle label="Group by" value={fairAttr} onChange={setFairAttr} options={[['traveller_type', 'Traveller type'], ['age_band', 'Age band']]} />
              <Toggle label="Detector" value={fairDet} onChange={setFairDet} options={[['system', 'System'], ['anomaly_model', 'Isolation Forest']]} />
            </div>}>
            {fair && (
              <div className="space-y-3">
                <div className="flex flex-wrap items-center gap-3">
                  <div><div className="text-3xl font-bold">{fair.equalized_odds_difference == null ? '—' : pct(fair.equalized_odds_difference)}</div>
                    <div className="text-[11px] uppercase text-slate-500">Equalized-odds difference</div></div>
                  <div><div className="text-3xl font-bold">{fair.demographic_parity_difference == null ? '—' : pct(fair.demographic_parity_difference)}</div>
                    <div className="text-[11px] uppercase text-slate-500">Flag-rate (parity) difference</div></div>
                  <Chip tone={fair.verdict === 'within_tolerance' ? 'green' : fair.verdict === 'review' ? 'amber' : 'slate'}>
                    {fair.verdict === 'within_tolerance' ? `Within ${pct(report.fairness.tolerance, 0)} tolerance`
                      : fair.verdict === 'review' ? `Review: gap above ${pct(report.fairness.tolerance, 0)}` : 'Insufficient data'}
                  </Chip>
                  {fair.low_confidence && <Chip tone="amber">Small groups — gaps are noisy</Chip>}
                </div>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                  <ResponsiveContainer width="100%" height={Math.max(150, fairBars.length * 80)}>
                    <BarChart data={fairBars} layout="vertical" stackOffset="sign" margin={{ top: 4, right: 24, bottom: 4, left: 8 }}>
                      <CartesianGrid stroke={INK.grid} horizontal={false} />
                      <XAxis type="number" tickFormatter={(v) => `${Math.abs(v)}%`} {...axis} />
                      <YAxis type="category" dataKey="group" width={110} {...axis} />
                      <Tooltip formatter={(v) => `${Math.abs(v).toFixed(1)}%`} /><Legend verticalAlign="top" />
                      <ReferenceLine x={0} stroke="#334155" />
                      <Bar dataKey="under" name="Missed (underprediction)" stackId="s" fill={C.orange}>
                        <LabelList dataKey="under" position="insideLeft" formatter={(v) => (v ? `${Math.abs(v).toFixed(1)}%` : '')} fill="#fff" fontSize={11} />
                      </Bar>
                      <Bar dataKey="over" name="False alarm (overprediction)" stackId="s" fill={C.blue}>
                        <LabelList dataKey="over" position="insideRight" formatter={(v) => (v ? `${v.toFixed(1)}%` : '')} fill="#fff" fontSize={11} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                  <Table head={['Group', 'n (susp./safe)', 'Detection', 'False alarm', 'Flag rate']}>
                    {fair.groups.map((g) => (
                      <tr key={g.group}>
                        <td className="py-2 pr-3 font-medium">{g.group}{g.low_confidence && <span title="fewer than 15 cases in a class" className="ml-1 text-amber-600">⚠</span>}</td>
                        <td className="py-2 pr-3">{g.n} ({g.n_suspicious}/{g.n_safe})</td>
                        <td className="py-2 pr-3 px-2" style={heat(g.tpr)}>{pct(g.tpr)}</td>
                        <td className="py-2 pr-3 px-2" style={heat(g.fpr == null ? null : 1 - g.fpr)}>{pct(g.fpr)}</td>
                        <td className="py-2 pr-3">{pct(g.selection_rate)}</td>
                      </tr>
                    ))}
                  </Table>
                </div>
                <p className="text-xs text-slate-500">{report.fairness.note}</p>
              </div>
            )}
          </Card>

          {/* ------------------------------------------------ SHAP + timing */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
            <Card title="Explainability — what drives the safety score (SHAP)">
              {shapRows.length ? (
                <>
                  <ResponsiveContainer width="100%" height={220}>
                    <BarChart data={shapRows} layout="vertical" margin={{ top: 4, right: 30, bottom: 4, left: 20 }}>
                      <CartesianGrid stroke={INK.grid} horizontal={false} />
                      <XAxis type="number" {...axis} /><YAxis type="category" dataKey="feature" width={100} {...axis} />
                      <Tooltip formatter={(v) => `${v} pts`} />
                      <Bar dataKey="value" name="Mean |contribution| (safety points)">
                        {shapRows.map((r, i) => <Cell key={r.feature} fill={i === 0 ? C.blue : '#7fb0ea'} />)}
                        <LabelList dataKey="value" position="right" fontSize={11} fill={INK.axis} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                  <p className="text-xs text-slate-500">Mean absolute SHAP contribution over {report.explainability.n_samples} evaluated scenarios.</p>
                </>
              ) : <p className="text-sm text-slate-500">SHAP is unavailable while the rule-based fallback is active (no trained safety model).</p>}
            </Card>

            <Card title="Detection & response time">
              <div className="grid grid-cols-3 gap-3 text-center mb-3">
                <div><div className="text-xl font-bold">{num(h.avg_detection_delay_min, 1)}<span className="text-xs"> min</span></div><div className="text-[11px] uppercase text-slate-500">avg detection delay</div></div>
                <div><div className="text-xl font-bold">{num(h.p90_detection_delay_min, 1)}<span className="text-xs"> min</span></div><div className="text-[11px] uppercase text-slate-500">p90 delay</div></div>
                <div><div className="text-xl font-bold">{num(h.inference_ms_per_ping, 3)}<span className="text-xs"> ms</span></div><div className="text-[11px] uppercase text-slate-500">inference / ping</div></div>
              </div>
              <Table head={['Response (real incidents)', 'n', 'Mean', 'Median', 'p90']}>
                {[['acknowledge', 'Detected → acknowledged'], ['dispatch', 'Detected → dispatched'], ['resolve', 'Detected → resolved']].map(([k, label]) => (
                  <tr key={k}>
                    <td className="py-2 pr-3">{label}</td><td className="py-2 pr-3">{resp.all[k].n}</td>
                    <td className="py-2 pr-3">{dur(resp.all[k].mean_s)}</td><td className="py-2 pr-3">{dur(resp.all[k].median_s)}</td><td className="py-2 pr-3">{dur(resp.all[k].p90_s)}</td>
                  </tr>
                ))}
              </Table>
              <p className="text-xs text-slate-500 mt-2">
                {resp.all.incidents} incident(s) on record ({resp.simulated.incidents} from simulated tourists). Response times only exist once an operator acts on an incident in the Incidents page.
              </p>
            </Card>
          </div>
        </>
      )}

      {/* ------------------------------------------------ registry + drift (independent of a run) */}
      <Card title="Model registry & training information">
        {!registry ? <p className="text-sm text-slate-500">No registry found — run <code>python -m app.ml.train_all</code>.</p> : (
          <Table head={['Model', 'Type', 'Version', 'Status', 'Trained', 'Data hash', 'Training metrics (hold-out)']}>
            {Object.entries(registry).flatMap(([name, entry]) =>
              [...entry.versions].reverse().slice(0, 4).map((v) => {
                const m = v.metrics_summary || {}
                const active = v.version === entry.active_version
                const summary = m.f1 != null ? `precision ${num(m.precision)} · recall ${num(m.recall)} · F1 ${num(m.f1)} · AUC ${num(m.roc_auc, 3)}`
                  : m.r2 != null ? `R² ${num(m.r2, 3)} · MAE ${num(m.mae)} (baseline ${num(m.baseline_mae)})`
                    : m.silhouette != null ? `${m.n_clusters} clusters · silhouette ${num(m.silhouette, 3)}` : '—'
                return (
                  <tr key={`${name}-${v.version}`} className={active ? 'font-semibold' : 'text-slate-500'}>
                    <td className="py-2 pr-3 capitalize">{name}</td><td className="py-2 pr-3">{m.model || '—'}</td>
                    <td className="py-2 pr-3">v{v.version}</td>
                    <td className="py-2 pr-3">{active ? <Chip tone="green">active</Chip> : <Chip>archived</Chip>}</td>
                    <td className="py-2 pr-3 whitespace-nowrap">{v.trained_at?.slice(0, 16).replace('T', ' ')}</td>
                    <td className="py-2 pr-3 font-mono text-xs">{v.dataset_hash}</td>
                    <td className="py-2 pr-3 text-xs">{summary}</td>
                  </tr>
                )
              }))}
          </Table>
        )}
        <p className="text-xs text-slate-500 mt-2">
          Training data is synthetic with a fixed seed (reproducible). Hold-out metrics above describe the training split; the scenario evaluation above is an independent test.
        </p>
      </Card>

      <Card title="Data drift (live traffic vs training data)">
        <p className="text-xs text-slate-500 mb-2">
          Compares recent live ping speeds with the training distribution (PSI: &lt;0.1 stable, &lt;0.25 moderate). Simulated tourists walk at a steady pace, so heavy simulation traffic will show as drift.
        </p>
        {!drift ? <p className="text-sm text-slate-500">Drift report unavailable.</p>
          : !drift.available ? <p className="text-sm text-slate-500">{drift.reason}</p> : (
            <Table head={['Feature', 'PSI', 'Verdict', 'Reference n', 'Live n']}>
              {drift.features.map((f) => (
                <tr key={f.feature}>
                  <td className="py-2 pr-3 font-mono text-xs">{f.feature}</td><td className="py-2 pr-3">{num(f.psi, 3)}</td>
                  <td className="py-2 pr-3"><Chip tone={f.verdict === 'stable' ? 'green' : f.verdict.startsWith('moderate') ? 'amber' : 'red'}>{f.verdict}</Chip></td>
                  <td className="py-2 pr-3">{f.n_reference}</td><td className="py-2 pr-3">{f.n_live}</td>
                </tr>
              ))}
            </Table>
          )}
      </Card>
    </div>
  )
}
